from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill


def scrivi_report(dettaglio, cap, file):
    wb = Workbook()
    ws = wb.active
    ws.title = "Misure"
    ws.append(list(dettaglio.columns))
    rosso = PatternFill("solid", fgColor="FFC7CE")
    for riga in dettaglio.itertuples(index=False):
        ws.append([v.item() if hasattr(v, "item") else v for v in riga])
        if not riga.ok:
            for c in ws[ws.max_row]:
                c.fill = rosso
    ws2 = wb.create_sheet("Capacità")
    ws2.append(["quota", *cap.columns])
    for q, r in cap.iterrows():
        ws2.append([q, *[round(float(x), 4) for x in r]])
    for foglio in (ws, ws2):
        for c in foglio[1]:
            c.font = Font(bold=True)
    wb.save(file)
